import { test, expect } from '@playwright/test';

test.describe('Video Player Responsive Tablet Viewport', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/video-player');
  });

  test('should resize video player proportionally on tablet viewports', async ({ page }) => {
    // Setup: Open the video player page
    await page.getByRole('heading', { name: /video player/i }).click();

    // Verify initial desktop viewport size
    const desktopWidth = page.getByRole('heading', { name: /video player/i }).boundingBox().width;
    const desktopHeight = page.getByRole('heading', { name: /video player/i }).boundingBox().height;
    expect(desktopWidth).toBeGreaterThan(1024);
    expect(desktopHeight).toBeGreaterThan(768);

    // Verify initial video player dimensions
    const videoPlayer = page.getByRole('region', { name: /video player/i });
    const videoWidth = await videoPlayer.boundingBox().width;
    const videoHeight = await videoPlayer.boundingBox().height;
    expect(videoWidth).toBeGreaterThan(0);
    expect(videoHeight).toBeGreaterThan(0);

    // Setup: Trigger tablet viewport
    await page.evaluate(() => {
      window.matchMedia('(max-width: 1024px)').addEventListener('change', (e) => {
        if (e.matches) {
          window.matchMedia('(max-width: 1024px)').removeEventListener('change');
          window.matchMedia('(min-width: 1025px)').removeEventListener('change');
        }
      });
    });

    // Verify video player resizes on tablet viewport
    await page.evaluate(() => {
      window.matchMedia('(max-width: 1024px)').addListener('change', (e) => {
        if (e.matches) {
          const video = document.querySelector('video');
          video.style.width = '100%';
          video.style.height = 'auto';
        }
      });
    });

    // Verify video player dimensions on tablet viewport
    const videoWidthTablet = await videoPlayer.boundingBox().width;
    const videoHeightTablet = await videoPlayer.boundingBox().height;
    expect(videoWidthTablet).toBeLessThanOrEqual(1024);
    expect(videoHeightTablet).toBeLessThanOrEqual(768);

    // Verify video controls are visible and functional
    const playButton = page.getByRole('button', { name: /play/i });
    await expect(playButton).toBeVisible();
    await playButton.click();

    // Verify video is playing
    const playbackStatus = page.getByRole('status');
    await expect(playbackStatus).toContainText('Playing');

    // Verify video player maintains aspect ratio
    const aspectRatio = videoWidthTablet / videoHeightTablet;
    expect(aspectRatio).toBeGreaterThanOrEqual(1);

    // Verify controls are still visible and functional on tablet viewport
    await expect(playButton).toBeVisible();
    await expect(playButton).toBeEnabled();

    // Verify video player resizes back to desktop viewport
    await page.evaluate(() => {
      window.matchMedia('(min-width: 1025px)').addListener('change', (e) => {
        if (e.matches) {
          window.matchMedia('(max-width: 1024px)').removeListener('change');
          window.matchMedia('(min-width: 1025px)').removeListener('change');
        }
      });
    });

    // Verify video player dimensions return to desktop viewport
    const videoWidthDesktop = await videoPlayer.boundingBox().width;
    const videoHeightDesktop = await videoPlayer.boundingBox().height;
    expect(videoWidthDesktop).toBeGreaterThan(1024);
    expect(videoHeightDesktop).toBeGreaterThan(768);
  });

  test('should handle video player scaling issues on tablet viewports', async ({ page }) => {
    // Setup: Open the video player page
    await page.getByRole('heading', { name: /video player/i }).click();

    // Verify initial desktop viewport size
    const desktopWidth = page.getByRole('heading', { name: /video player/i }).boundingBox().width;
    const desktopHeight = page.getByRole('heading', { name: /video player/i }).boundingBox().height;
    expect(desktopWidth).toBeGreaterThan(1024);
    expect(desktopHeight).toBeGreaterThan(768);

    // Verify initial video player dimensions
    const videoPlayer = page.getByRole('region', { name: /video player/i });
    const videoWidth = await videoPlayer.boundingBox().width;
    const videoHeight = await videoPlayer.boundingBox().height;
    expect(videoWidth).toBeGreaterThan(0);
    expect(videoHeight).toBeGreaterThan(0);

    // Setup: Trigger tablet viewport
    await page.evaluate(() => {
      window.matchMedia('(max-width: 1024px)').addEventListener('change', (e) => {
        if (e.matches) {
          window.matchMedia('(max-width: 1024px)').removeEventListener('change');
          window.matchMedia('(min-width: 1025px)').removeEventListener('change');
        }
      });
    });

    // Verify video player fails to load on tablet viewport
    await page.evaluate(() => {
      window.matchMedia('(max-width: 1024px)').addListener('change', (e) => {
        if (e.matches) {
          const video = document.querySelector('video');
          video.src = 'invalid-video-source';
        }
      });
    });

    // Verify error message is displayed
    const errorMessage = page.getByText(/error loading video/i);
    await expect(errorMessage).toBeVisible();

    // Verify video player does not play
    const playbackStatus = page.getByRole('status');
    await expect(playbackStatus).toContainText('Error');

    // Verify video controls are still visible and functional
    const playButton = page.getByRole('button', { name: /play/i });
    await expect(playButton).toBeVisible();
    await expect(playButton).toBeEnabled();

    // Verify video player resizes back to desktop viewport
    await page.evaluate(() => {
      window.matchMedia('(min-width: 1025px)').addListener('change', (e) => {
        if (e.matches) {
          window.matchMedia('(max-width: 1024px)').removeListener('change');
          window.matchMedia('(min-width: 1025px)').removeListener('change');
        }
      });
    });

    // Verify video player dimensions return to desktop viewport
    const videoWidthDesktop = await videoPlayer.boundingBox().width;
    const videoHeightDesktop = await videoPlayer.boundingBox().height;
    expect(videoWidthDesktop).toBeGreaterThan(1024);
    expect(videoHeightDesktop).toBeGreaterThan(768);
  });
});
